try {
  const aiContent = $input.first().json.choices[0].message.content;
  const startIndex = aiContent.indexOf('[');
  const endIndex = aiContent.lastIndexOf(']');
  if (startIndex === -1 || endIndex === -1) {
    throw new Error("Could not find a valid JSON array in the AI's response.");
  }
  const jsonString = aiContent.slice(startIndex, endIndex + 1);
  const recommendations = JSON.parse(jsonString);

  return recommendations.map((rec, index) => ({
    json: {
      id: `rec_${index + 1}`,
      description: rec.name || `Recommendation ${index + 1}`,
      colors: rec.colors || [],
      reasoning: rec.reasoning || ""
    }
  }));
} catch (error) {
  console.error("Full AI Content:", $input.first().json.choices[0].message.content);
  throw new Error(`Failed to parse recommendations: ${error.message}`);
}

const geminiResponse = $(' Create Kie.ai Task').item.json;
const recommendationData = $('Loop Over Recommendations').item.json;

let generatedImage = null;

if (geminiResponse.candidates && 
    geminiResponse.candidates[0] && 
    geminiResponse.candidates[0].content && 
    geminiResponse.candidates[0].content.parts) {

  // Loop through all parts to find the one with inlineData
  for (const part of geminiResponse.candidates[0].content.parts) {
    if (part.inlineData) {
      const base64Data = part.inlineData.data;
      const mimeType = part.inlineData.mimeType || 'image/jpeg';
      generatedImage = `data:${mimeType};base64,${base64Data}`;
      break;
    }
  }
}

if (!generatedImage) {
  generatedImage = $('Webhook Trigger').first().json.body.base64Images[0];
}

return [{
  json: {
    id: recommendationData.id,
    description: recommendationData.description,
    colors: recommendationData.colors,
    reasoning: recommendationData.reasoning,
    generatedImage: generatedImage
  }
}];

const allItems = $input.all();
const validResults = allItems.map(item => item.json).filter(item => item && item.id);
const sortedResults = validResults.sort((a, b) => a.id.localeCompare(b.id));

return [{
  json: {
    recommendations: sortedResults
  }
}];
